sources=json.loads('{"ActualTwoDescentFractionalGeneratorModuleRebuild318": "module\\npublic import ActualTwoDescentOriginalPrincipalInverseCertificateRebuild318\\npublic section\\nnoncomputable section\\nnamespace ActualTwoDescentFractionalGeneratorModuleRebuild318\\nvariable (R F : Type*) [CommRing R] [Field F] [Algebra R F]\\n\\ndef coefficientMap (g : F) : R →ₗ[R] F where\\n  toFun r := algebraMap R F r*g\\n  map_add\' r s := by rw [map_add,add_mul]\\n  map_smul\' r s := by\\n    change algebraMap R F (r*s)*g=algebraMap R F r*(algebraMap R F s*g)\\n    rw [map_mul,mul_assoc]\\n\\ndef lattice (g : F) : Submodule R F := (coefficientMap R F g).range\\n\\nlemma mem_lattice (g z : F) : z ∈ lattice R F g ↔\\n    ∃ r : R,algebraMap R F r*g=z := Iff.rfl\\n\\n/-- Full image, with the original scalar embedding retained. -/\\ndef frame (g : F) (hg : g ≠ 0) (hi : Function.Injective (algebraMap R F)) :\\n    R ≃ₗ[R] lattice R F g :=\\n  LinearEquiv.ofBijective (coefficientMap R F g).rangeRestrict (by\\n    constructor\\n    · intro r s h\\n      exact hi (mul_right_cancel₀ hg (congrArg Subtype.val h))\\n    · intro z\\n      obtain ⟨r,hr⟩ := z.property\\n      exact ⟨r,Subtype.ext hr⟩)\\n\\nlemma frame_value (g : F) (hg : g ≠ 0) (hi : Function.Injective (algebraMap R F))\\n    (r : R) : (frame R F g hg hi r : F)=algebraMap R F r*g := rfl\\nend ActualTwoDescentFractionalGeneratorModuleRebuild318\\n", "ActualTwoDescentLocalizedIdealNativePullbackRebuild318": "module\\npublic import ActualTwoDescentFractionalGeneratorModuleRebuild318\\npublic import ActualTwoDescentIdealLocalizationAdjoint318\\npublic import TildePullback318\\npublic section\\nnoncomputable section\\nnamespace ActualTwoDescentLocalizedIdealNativePullbackRebuild318\\nopen AlgebraicGeometry CategoryTheory\\nopen scoped TensorProduct ChangeOfRings\\nuniverse u\\nvariable {R : Type u} [CommRing R] (S : Type u) [CommRing S] [Algebra R S]\\n  (T : Submonoid R) [IsLocalization T S] (I : Ideal R)\\nlocal notation \\"f\\" => CommRingCat.ofHom (algebraMap R S)\\n\\n/-- Native pullback of the literal ideal sheaf, normalized by the actual\\nlocalization tensor map rather than an abstract line-bundle choice. -/\\ndef iso :\\n    (Scheme.Modules.pullback (Spec.map f)).obj\\n      (tilde (R:=CommRingCat.of R) (ModuleCat.of R I)) ≅\\n    tilde (R:=CommRingCat.of S) (ModuleCat.of S (I.map (algebraMap R S))) :=\\n  (TildePullback318.pullbackIso f).app (ModuleCat.of R I) ≪≫\\n    (tilde.functor (CommRingCat.of S)).mapIso\\n      (ActualTwoDescentIdealLocalizationAdjoint318.idealExtensionEquiv S T I).toModuleIso\\n\\nlemma hom_formula : (iso S T I).hom=\\n    (TildePullback318.pullbackIso f).hom.app (ModuleCat.of R I) ≫\\n    (tilde.functor (CommRingCat.of S)).map\\n      (ActualTwoDescentIdealLocalizationAdjoint318.idealExtensionEquiv S T I).toModuleIso.hom := rfl\\n\\n/-- Exact original ideal inclusion on every one-tensor, inherited from\\nthe specified extension map and not merely inferred from bijectivity. -/\\nlemma one_tensor (x : I) :\\n    (ActualTwoDescentIdealLocalizationAdjoint318.idealExtensionEquiv S T I\\n      ((1:S) ⊗ₜ[R,algebraMap R S] x) : S)=algebraMap R S (x:R) := by\\n  change (ActualTwoDescentLocalizedIdealTensorEquivalence318.localizedIdealTensorEquiv S T I\\n    ((1:S) ⊗ₜ[R] x) : S)=_\\n  rw [ActualTwoDescentLocalizedIdealTensorEquivalence318.actual_localized_ideal_tensor_value,one_mul]\\nend ActualTwoDescentLocalizedIdealNativePullbackRebuild318\\n", "ActualTwoDescentOriginalAffineAtPrimePullbackRebuild318": "module\\npublic import ActualTwoDescentLocalizedIdealNativePullbackRebuild318\\npublic section\\nnoncomputable section\\nnamespace ActualTwoDescentOriginalAffineAtPrimePullbackRebuild318\\nopen AlgebraicGeometry CategoryTheory\\nopen ActualTwoDescentOriginalTwoChartCubicScheme318 ActualTwoDescentOriginalDegreeZeroIdealSheaf318\\nopen ActualTwoDescentOriginalIdealAffineRestriction318 ActualTwoDescentOriginalRootIdeals318\\nopen ActualTwoDescentAffineChartCoordinates318\\nuniverse u\\nvariable {K : Type u} [Field K] [CharZero K]\\n\\ndef localMap (n : K) (P : Ideal (AffineChart n)) [P.IsPrime] :\\n    Spec (CommRingCat.of (Localization.AtPrime P)) ⟶ affineScheme n :=\\n  Spec.map (CommRingCat.ofHom (algebraMap (AffineChart n) (Localization.AtPrime P)))\\ndef map (n : K) (P : Ideal (AffineChart n)) [P.IsPrime] := localMap n P ≫ affineChart n\\n\\n/-- Pullback of the SAME old global ideal sheaf to every actual affine\\nlocal spectrum. No localization-at-a-point open immersion is assumed. -/\\ndef iso (n : K) (i : Fin 3) (P : Ideal (AffineChart n)) [P.IsPrime] :\\n    (Scheme.Modules.pullback (map n P)).obj (originalRootIdealSheaf n i) ≅\\n      tilde (R:=CommRingCat.of (Localization.AtPrime P))\\n        (ModuleCat.of (Localization.AtPrime P)\\n          ((rootIdeal n i).map (algebraMap (AffineChart n) (Localization.AtPrime P)))) :=\\n  ((Scheme.Modules.pullbackComp (localMap n P) (affineChart n)).app\\n      (originalRootIdealSheaf n i)).symm ≪≫\\n  (Scheme.Modules.pullback (localMap n P)).mapIso\\n    (((Scheme.Modules.restrictFunctorIsoPullback (affineChart n)).app\\n      (originalRootIdealSheaf n i)).symm ≪≫ originalAffineRestrictionIso n i) ≪≫\\n  ActualTwoDescentLocalizedIdealNativePullbackRebuild318.iso\\n    (Localization.AtPrime P) P.primeCompl (rootIdeal n i)\\n\\n/-- Every affine prime away from Ta has the full regular ideal image. -/\\ntheorem off_root_ideal (n : K) (i : Fin 3) (P : Ideal (AffineChart n)) [P.IsPrime]\\n    (hP : P ≠ rootIdeal n i) :\\n    (rootIdeal n i).map (algebraMap (AffineChart n) (Localization.AtPrime P))=⊤ := by\\n  have hx : rootNumerator n i ∈ rootIdeal n i :=\\n    (ActualTwoDescentOriginalRootAffineSupport318.actual_root_prime_support\\n      n i (rootIdeal n i)).mpr rfl\\n  exact Ideal.eq_top_of_isUnit_mem _ (Ideal.mem_map_of_mem _ hx)\\n    (ActualTwoDescentOriginalRootAffineSupport318.actual_root_unit_off_support n i P hP)\\n\\nend ActualTwoDescentOriginalAffineAtPrimePullbackRebuild318\\n", "ActualTwoDescentOriginalLocalFieldEmbeddingsRebuild318": "module\\npublic import ActualTwoDescentOriginalAffineAtPrimePullbackRebuild318\\npublic section\\nnoncomputable section\\nnamespace ActualTwoDescentOriginalLocalFieldEmbeddingsRebuild318\\nopen AlgebraicGeometry\\nopen ActualTwoDescentOriginalTwoChartCubicScheme318 ActualTwoDescentOriginalIntegralSchemeRebuild318\\nopen ActualTwoDescentOriginalMarkedStalksRebuild318 ActualTwoDescentOriginalRootLocalParameter318\\nopen ActualTwoDescentInfinityLocalParameter318\\nvariable {K : Type*} [Field K] [CharZero K]\\n\\n/-- Both local coefficient embeddings factor through the ACTUAL\\noriginal marked stalk and its canonical generic specialization. -/\\ndef rootEmbedding (n : K) (i : Fin 3) : RootLocalRing n i →+* (originalCubicScheme n).functionField :=\\n  (algebraMap (RootStalk n i) (originalCubicScheme n).functionField).comp (rootEquiv n i).symm.toRingHom\\n\\ndef infinityEmbedding (n : K) : InfinityLocalRing n →+* (originalCubicScheme n).functionField :=\\n  (algebraMap (InfinityStalk n) (originalCubicScheme n).functionField).comp (infinityEquiv n).symm.toRingHom\\n\\nlemma root_injective (n : K) (i : Fin 3) : Function.Injective (rootEmbedding n i) :=\\n  (IsFractionRing.injective _ _).comp (rootEquiv n i).symm.injective\\nlemma infinity_injective (n : K) : Function.Injective (infinityEmbedding n) :=\\n  (IsFractionRing.injective _ _).comp (infinityEquiv n).symm.injective\\n\\nlemma root_named (n : K) (i : Fin 3) : rootEmbedding n i (rootLocalF n i)=\\n    ActualTwoDescentOriginalGenericFunctionsRebuild318.root n\\n      (ActualTwoDescentOriginalRootIdeals318.root n i) :=\\n  ActualTwoDescentOriginalRootGenericSquareRebuild318.root_square n i\\n\\nlemma infinity_parameter (n : K) : infinityEmbedding n (localU n)=\\n    algebraMap (InfinityStalk n) (originalCubicScheme n).functionField (infinityU n) := rfl\\nlemma infinity_parameter_nonzero (n : K) : infinityEmbedding n (localU n) ≠ 0 := by\\n  rw [infinity_parameter]\\n  exact (map_ne_zero_iff _ (IsFractionRing.injective _ _)).mpr\\n    (ActualTwoDescentOriginalStalkFactorsRebuild318.infinity_uniformizer n).ne_zero\\nend ActualTwoDescentOriginalLocalFieldEmbeddingsRebuild318\\n", "ActualTwoDescentOriginalRootFractionalModuleRebuild318": "module\\npublic import ActualTwoDescentOriginalLocalFieldEmbeddingsRebuild318\\npublic section\\nnoncomputable section\\nnamespace ActualTwoDescentOriginalRootFractionalModuleRebuild318\\nopen ActualTwoDescentOriginalTwoChartCubicScheme318 ActualTwoDescentOriginalIntegralSchemeRebuild318\\nopen ActualTwoDescentOriginalRootLocalParameter318 ActualTwoDescentOriginalRootNativeDVR318\\nopen ActualTwoDescentOriginalRootIdeals318 ActualTwoDescentAffineChartCoordinates318\\nopen ActualTwoDescentOriginalLocalFieldEmbeddingsRebuild318\\nuniverse u\\nvariable {K : Type u} [Field K] [CharZero K]\\nlocal instance (n : K) (i : Fin 3) : Algebra (RootLocalRing n i) ((originalCubicScheme n).functionField) := (rootEmbedding n i).toAlgebra\\n\\ndef extendedIdeal (n : K) (i : Fin 3) : Ideal (RootLocalRing n i) :=\\n  (rootIdeal n i).map (algebraMap (AffineChart n) (RootLocalRing n i))\\nlemma extendedIdeal_eq (n : K) (hn : n ≠ 0) (i : Fin 3) :\\n    extendedIdeal n i=Ideal.span {rootLocalY n i} := by\\n  rw [extendedIdeal,Localization.AtPrime.map_eq_maximalIdeal,\\n    actual_root_maximal_principal n hn i]\\n\\ndef lattice (n : K) (i : Fin 3) : Submodule (RootLocalRing n i) ((originalCubicScheme n).functionField) :=\\n  ActualTwoDescentFractionalGeneratorModuleRebuild318.lattice (RootLocalRing n i) ((originalCubicScheme n).functionField)\\n    (rootEmbedding n i (rootLocalY n i))\\n\\ndef frame (n : K) (i : Fin 3) : RootLocalRing n i ≃ₗ[RootLocalRing n i] lattice n i :=\\n  ActualTwoDescentFractionalGeneratorModuleRebuild318.frame (RootLocalRing n i) ((originalCubicScheme n).functionField) _\\n    ((map_ne_zero_iff _ (root_injective n i)).mpr (actual_root_local_y_nonzero n i))\\n    (root_injective n i)\\n\\n/-- Full original root ideal image equals yR inside the SAME original\\nfunction field, with the actual coefficient embedding fixed. -/\\ndef equivalence (n : K) (hn : n ≠ 0) (i : Fin 3) : extendedIdeal n i ≃ₗ[RootLocalRing n i] lattice n i :=\\n  (ActualTwoDescentPrincipalIdealModuleFrame318.principalModuleFrame\\n    (extendedIdeal n i) (rootLocalY n i) (extendedIdeal_eq n hn i)\\n    (actual_root_local_y_nonzero n i)).symm.trans (frame n i)\\n\\nlemma value (n : K) (hn : n ≠ 0) (i : Fin 3) (x : extendedIdeal n i) :\\n    (equivalence n hn i x : (originalCubicScheme n).functionField)=rootEmbedding n i (x : RootLocalRing n i) := by\\n  let e := ActualTwoDescentPrincipalIdealModuleFrame318.principalModuleFrame\\n    (extendedIdeal n i) (rootLocalY n i) (extendedIdeal_eq n hn i)\\n    (actual_root_local_y_nonzero n i)\\n  have hx := congrArg (fun z : extendedIdeal n i => (z : RootLocalRing n i)) (e.apply_symm_apply x)\\n  change (e.symm x)*rootLocalY n i=(x : RootLocalRing n i) at hx\\n  change rootEmbedding n i (e.symm x)*rootEmbedding n i (rootLocalY n i)=_\\n  rw [←map_mul,hx]\\n\\nlemma mem_lattice (n : K) (i : Fin 3) (z : (originalCubicScheme n).functionField) : z ∈ lattice n i ↔\\n    ∃ r : RootLocalRing n i, rootEmbedding n i r*rootEmbedding n i (rootLocalY n i)=z := Iff.rfl\\nend ActualTwoDescentOriginalRootFractionalModuleRebuild318\\n", "ActualTwoDescentOriginalRootFractionalSheafRebuild318": "module\\npublic import ActualTwoDescentOriginalRootFractionalModuleRebuild318\\npublic section\\nnoncomputable section\\nnamespace ActualTwoDescentOriginalRootFractionalSheafRebuild318\\nopen AlgebraicGeometry CategoryTheory\\nopen ActualTwoDescentOriginalDegreeZeroIdealSheaf318 ActualTwoDescentOriginalRootIdeals318\\nopen ActualTwoDescentOriginalRootLocalParameter318 ActualTwoDescentOriginalRootFractionalModuleRebuild318\\nuniverse u\\nvariable {K : Type u} [Field K] [CharZero K]\\n\\n/-- Native pullback of the EXISTING global ideal sheaf to the literal\\nroot local spectrum, identified with the exact fractional yR module. -/\\ndef iso (n : K) (hn : n ≠ 0) (i : Fin 3) :\\n    (Scheme.Modules.pullback\\n      (ActualTwoDescentOriginalAffineAtPrimePullbackRebuild318.map n (rootIdeal n i))).obj\\n      (originalRootIdealSheaf n i) ≅\\n    tilde (R:=CommRingCat.of (RootLocalRing n i)) (ModuleCat.of (RootLocalRing n i) (lattice n i)) :=\\n  ActualTwoDescentOriginalAffineAtPrimePullbackRebuild318.iso n i (rootIdeal n i) ≪≫\\n    (tilde.functor (CommRingCat.of (RootLocalRing n i))).mapIso (equivalence n hn i).toModuleIso\\n\\nlemma hom_formula (n : K) (hn : n ≠ 0) (i : Fin 3) : (iso n hn i).hom=\\n    (ActualTwoDescentOriginalAffineAtPrimePullbackRebuild318.iso n i (rootIdeal n i)).hom ≫\\n    (tilde.functor (CommRingCat.of (RootLocalRing n i))).map (equivalence n hn i).toModuleIso.hom := rfl\\nend ActualTwoDescentOriginalRootFractionalSheafRebuild318\\n", "ActualTwoDescentOriginalInfinityLocalPullbackRebuild318": "module\\npublic import ActualTwoDescentOriginalRootFractionalSheafRebuild318\\npublic import IdentityCotangent318\\npublic section\\nnoncomputable section\\nnamespace ActualTwoDescentOriginalInfinityLocalPullbackRebuild318\\nopen AlgebraicGeometry CategoryTheory\\nopen ActualTwoDescentOriginalTwoChartCubicScheme318 ActualTwoDescentOriginalDegreeZeroIdealSheaf318\\nopen ActualTwoDescentOriginalIdealInfinityFrame318 ActualTwoDescentInfinityLocalParameter318\\nopen ActualTwoDescentInfinityChartRing318\\nuniverse u\\nvariable {K : Type u} [Field K] [CharZero K]\\n\\ndef localMap (n : K) : Spec (CommRingCat.of (InfinityLocalRing n)) ⟶ infinityScheme n :=\\n  Spec.map (CommRingCat.ofHom (algebraMap (InfinityChart n) (InfinityLocalRing n)))\\ndef map (n : K) := localMap n ≫ infinityChart n\\n\\n/-- Pull the exact old infinity projection frame to the actual origin\\nlocal spectrum; do not replace it with a chosen trivialization. -/\\ndef frame (n : K) (i : Fin 3) :\\n    (Scheme.Modules.pullback (map n)).obj (originalRootIdealSheaf n i) ≅\\n    SheafOfModules.unit (Spec (CommRingCat.of (InfinityLocalRing n))).ringCatSheaf :=\\n  ((Scheme.Modules.pullbackComp (localMap n) (infinityChart n)).app\\n      (originalRootIdealSheaf n i)).symm ≪≫\\n  (Scheme.Modules.pullback (localMap n)).mapIso\\n    (((Scheme.Modules.restrictFunctorIsoPullback (infinityChart n)).app\\n      (originalRootIdealSheaf n i)).symm ≪≫ originalInfinityFrame n i) ≪≫\\n  IdentityCotangent318.pullbackUnitIso (localMap n)\\nend ActualTwoDescentOriginalInfinityLocalPullbackRebuild318\\n", "ActualTwoDescentOriginalInfinityFractionalSheafRebuild318": "module\\npublic import ActualTwoDescentOriginalInfinityLocalPullbackRebuild318\\npublic section\\nnoncomputable section\\nnamespace ActualTwoDescentOriginalInfinityFractionalSheafRebuild318\\nopen AlgebraicGeometry CategoryTheory\\nopen ActualTwoDescentOriginalTwoChartCubicScheme318 ActualTwoDescentOriginalIntegralSchemeRebuild318\\nopen ActualTwoDescentOriginalDegreeZeroIdealSheaf318 ActualTwoDescentInfinityLocalParameter318\\nopen ActualTwoDescentOriginalLocalFieldEmbeddingsRebuild318\\nuniverse u\\nvariable {K : Type u} [Field K] [CharZero K]\\nlocal instance (n : K) : Algebra (InfinityLocalRing n) ((originalCubicScheme n).functionField) := (infinityEmbedding n).toAlgebra\\n\\ndef lattice (n : K) : Submodule (InfinityLocalRing n) ((originalCubicScheme n).functionField) :=\\n  ActualTwoDescentFractionalGeneratorModuleRebuild318.lattice (InfinityLocalRing n) ((originalCubicScheme n).functionField)\\n    (infinityEmbedding n (localU n))⁻¹\\n\\ndef moduleFrame (n : K) : InfinityLocalRing n ≃ₗ[InfinityLocalRing n] lattice n :=\\n  ActualTwoDescentFractionalGeneratorModuleRebuild318.frame (InfinityLocalRing n) ((originalCubicScheme n).functionField) _\\n    (inv_ne_zero (infinity_parameter_nonzero n)) (infinity_injective n)\\n\\n/-- Full local fractional module is u inverse times the ACTUAL local\\nring in the same original function field, not a pole-symbol token. -/\\nlemma mem_lattice (n : K) (z : (originalCubicScheme n).functionField) : z ∈ lattice n ↔\\n    ∃ r : InfinityLocalRing n,infinityEmbedding n r/(infinityEmbedding n (localU n))=z := by\\n  simp only [lattice,ActualTwoDescentFractionalGeneratorModuleRebuild318.mem_lattice,div_eq_mul_inv] <;> rfl\\n\\n/-- The exact old infinity frame, followed by the explicit b/u map.\\nGlobal compatibility with the affine fractional embedding is separate. -/\\ndef iso (n : K) (i : Fin 3) :\\n    (Scheme.Modules.pullback (ActualTwoDescentOriginalInfinityLocalPullbackRebuild318.map n)).obj\\n      (originalRootIdealSheaf n i) ≅\\n    tilde (R:=CommRingCat.of (InfinityLocalRing n)) (ModuleCat.of (InfinityLocalRing n) (lattice n)) :=\\n  ActualTwoDescentOriginalInfinityLocalPullbackRebuild318.frame n i ≪≫\\n  (tildeSelf (R:=CommRingCat.of (InfinityLocalRing n))).symm ≪≫\\n  (tilde.functor (CommRingCat.of (InfinityLocalRing n))).mapIso (moduleFrame n).toModuleIso\\n\\nlemma module_value (n : K) (r : InfinityLocalRing n) : (moduleFrame n r : (originalCubicScheme n).functionField)=\\n    infinityEmbedding n r/(infinityEmbedding n (localU n)) := by\\n  change infinityEmbedding n r*(infinityEmbedding n (localU n))⁻¹=_\\n  rw [div_eq_mul_inv]\\nend ActualTwoDescentOriginalInfinityFractionalSheafRebuild318\\n"}')
